/**
 * PSE Ownership Provider
 *
 * Reads data/pse-ownership.json (generated by
 * scripts/scrape-pse-ownership.ts, which scrapes real Public Ownership
 * Report filings from PSE Edge — see
 * src/services/scrapers/PSEEdgeScraper.ts's ParsedOwnership doc). A PSE
 * POR-1 filing only reports insider % (directors/officers/substantial
 * shareholders, summed) and public %, not a foreign/domestic
 * institutional split.
 *
 * Unlike pseFundamentalsProvider.ts, there is no synthetic fallback here
 * — a fabricated ownership breakdown is not shown; symbols with no real
 * record simply get an empty array (StockPage.tsx hides the Shareholdings
 * card entirely in that case, same as before this feature existed).
 */
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

export interface RealPseOwnershipRecord {
  reportDate: string | null;
  outstandingShares: number | null;
  sharesOwnedByPublic: number | null;
  publicOwnershipPercent: number | null;
  insiderOwnershipPercent: number | null;
}

type RealOwnershipMap = Record<string, RealPseOwnershipRecord | { error: string }>;

let realOwnershipCache: RealOwnershipMap | null = null;

function loadRealOwnershipMap(): RealOwnershipMap {
  if (realOwnershipCache !== null) return realOwnershipCache;
  let loaded: RealOwnershipMap = {};
  try {
    const raw = readFileSync(resolve(process.cwd(), 'data/pse-ownership.json'), 'utf-8');
    loaded = JSON.parse(raw).results ?? {};
  } catch {
    // File not generated yet (scripts/scrape-pse-ownership.ts hasn't been
    // run) — treat as "no real data available", not an error.
  }
  realOwnershipCache = loaded;
  return loaded;
}

/** Real ownership record for a symbol, or null if none is available.
 * Never fabricates a fallback — callers should render nothing rather
 * than a modeled substitute. */
export function loadRealPseOwnership(symbol: string): RealPseOwnershipRecord | null {
  const record = loadRealOwnershipMap()[symbol.toUpperCase()];
  if (!record || 'error' in record) return null;
  if (record.publicOwnershipPercent === null) return null;
  return record;
}
